    static AeonSkill[] Data() => new AeonSkill[]
    {
        new("ya0g", EyeSector.Yahweh, 0, AeonKind.Good, "첫 계명\u001FFirst Commandment", "돌에 새긴 첫 말씀이 흩어진 신도를 한 울타리 안에 묶습니다.\u001FThe first word carved in stone gathers scattered believers into one fold.", new[] { GodEffect.Guard(StatId.FollowerFaith, 6), GodEffect.Guard(StatId.Reputation, 2), GodEffect.Yearly(PersonalStatId.Integrity, 1) }, 0, 5, null),
        new("ya0e", EyeSector.Yahweh, 0, AeonKind.Evil, "질투의 불씨\u001FEmber of Jealousy", "다른 신을 섬기는 자를 향한 질투가 설교에 불을 붙입니다.\u001FJealousy toward those who serve other gods sets the sermons ablaze.", new[] { GodEffect.Gain(StatId.Doctrine, 9), GodEffect.Chance("Revelation", 4), GodEffect.Yearly(PersonalStatId.Ambition, 1) }, 1, 0, null),
        new("ya1g", EyeSector.Yahweh, 1, AeonKind.Good, "언약의 돌판\u001FTablets of the Covenant", "언약을 지키는 자에게만 문이 열려 교단의 경계가 단단해집니다.\u001FThe door opens only to those who keep the covenant; the cult's borders harden.", new[] { GodEffect.Guard(StatId.FollowerFaith, 8), GodEffect.Guard(StatId.Reputation, 2), GodEffect.Yearly(PersonalStatId.Integrity, 1) }, 0, 5, null),
        new("ya1e", EyeSector.Yahweh, 1, AeonKind.Evil, "불타는 떨기나무\u001FThe Burning Bush", "타지 않는 불꽃 앞에서 사람들은 이유를 묻지 않고 엎드립니다.\u001FBefore a flame that does not consume", new[] { GodEffect.Gain(StatId.Doctrine, 11), GodEffect.Chance("Revelation", 5), GodEffect.Yearly(PersonalStatId.Ambition, 1) }, 1, 0, null),
        new("ya2g", EyeSector.Yahweh, 2, AeonKind.Good, "안식의 율법\u001FLaw of Rest", "일곱째 날의 쉼이 지친 신도들의 믿음을 다시 채웁니다.\u001FThe rest of the seventh day refills the faith of weary believers.", new[] { GodEffect.Guard(StatId.FollowerFaith, 10), GodEffect.Guard(StatId.Reputation, 3), GodEffect.Yearly(PersonalStatId.Integrity, 1) }, 0, 5, null),
        new("ya2e", EyeSector.Yahweh, 2, AeonKind.Evil, "열 가지 재앙\u001FThe Ten Plagues", "강이 피로 물들자 의심하던 자들도 말씀을 따릅니다.\u001FWhen the river runs red", new[] { GodEffect.Gain(StatId.Doctrine, 13), GodEffect.Chance("Revelation", 6), GodEffect.Yearly(PersonalStatId.Ambition, 1) }, 2, 0, null),
        new("ya3g", EyeSector.Yahweh, 3, AeonKind.Good, "속죄의 제단\u001FAltar of Atonement", "흘린 피가 죄를 덮어 교단이 외부의 심판을 견딥니다.\u001FSpilled blood covers sin and the cult endures outside judgment.", new[] { GodEffect.Guard(StatId.FollowerFaith, 12), GodEffect.Guard(StatId.Reputation, 3), GodEffect.Yearly(PersonalStatId.Integrity, 1) }, 0, 5, null),
        new("ya3e", EyeSector.Yahweh, 3, AeonKind.Evil, "질투하는 이름\u001FThe Jealous Name", "부르는 것조차 두려운 이름이 신도들의 입을 다물게 합니다.\u001FA name too fearful to speak silences every believer's mouth.", new[] { GodEffect.Gain(StatId.Doctrine, 15), GodEffect.Chance("Revelation", 7), GodEffect.Yearly(PersonalStatId.Ambition, 1) }, 3, 0, null),
        new("ya4g", EyeSector.Yahweh, 4, AeonKind.Good, "지성소의 휘장\u001FVeil of the Holy of Holies", "휘장 너머의 거룩함이 교단의 가장 깊은 곳을 지킵니다.\u001FThe holiness behind the veil guards the cult's innermost place.", new[] { GodEffect.Guard(StatId.FollowerFaith, 14), GodEffect.Guard(StatId.Reputation, 4), GodEffect.Yearly(PersonalStatId.Integrity, 1) }, 0, 5, null),
        new("ya4e", EyeSector.Yahweh, 4, AeonKind.Evil, "만군의 진노\u001FWrath of Hosts", "하늘의 군대가 진노를 쏟아 거역하는 마을을 무릎 꿇립니다.\u001FThe heavenly host pours out its wrath and brings defiant towns to their knees.", new[] { GodEffect.Gain(StatId.Doctrine, 18), GodEffect.Chance("Revelation", 8), GodEffect.Yearly(PersonalStatId.Ambition, 1) }, 4, 0, null),
        new("ya5", EyeSector.Yahweh, 5, AeonKind.Gnosis, "야훼의 그노시스\u001FGnosis of Yahweh", "율법과 질투가 한 몸이었음을 깨닫고 그 신의 정체를 압니다.\u001FYou see that Law and jealousy were one body and know that god for what it is.", new[] { GodEffect.Gain(StatId.Doctrine, 5), GodEffect.Guard(StatId.FollowerFaith, 5), GodEffect.Resist(Pressure.Earth, 1), GodEffect.Chance("Revelation", 2) }, 1, 0, null),
        new("ya6", EyeSector.Yahweh, 6, AeonKind.Gnosis, "헤브도마스 돌파\u001FBreaching the Hebdomad", "일곱 하늘을 다스리던 율법이 더는 당신을 묶지 못합니다.\u001FThe Law that ruled the seven heavens can no longer bind you.", new[] { GodEffect.Gain(StatId.Doctrine, 10), GodEffect.Guard(StatId.FollowerFaith, 10), GodEffect.Resist(Pressure.Earth, 1), GodEffect.Chance("Revelation", 4) }, 1, 0, null),
        new("ya7", EyeSector.Yahweh, 7, AeonKind.Gnosis, "오그도아스\u001FThe Ogdoad", "계명 없는 여덟째 하늘에서 처음으로 자유롭게 숨을 쉽니다.\u001FIn the eighth heaven without commandments you breathe freely for the first time.", new[] { GodEffect.Gain(StatId.Doctrine, 15), GodEffect.Guard(StatId.FollowerFaith, 15), GodEffect.Resist(Pressure.Earth, 2), GodEffect.Chance("Revelation", 6) }, 1, 0, null),
        new("ya8", EyeSector.Yahweh, 8, AeonKind.Gnosis, "소피아의 그림자\u001FShadow of Sophia", "율법을 낳은 것이 지혜의 실수였다는 그림자를 봅니다.\u001FYou glimpse the shadow showing that the Law was born of Wisdom's mistake.", new[] { GodEffect.Gain(StatId.Doctrine, 20), GodEffect.Guard(StatId.FollowerFaith, 20), GodEffect.Resist(Pressure.Earth, 2), GodEffect.Chance("Revelation", 8) }, 1, 0, null),
        new("ya9", EyeSector.Yahweh, 9, AeonKind.Gnosis, "플레로마의 문턱\u001FThreshold of the Pleroma", "질투하는 신도 들어오지 못한 충만의 문 앞에 섭니다.\u001FYou stand at the gate of Fullness that even the jealous god could not enter.", new[] { GodEffect.Gain(StatId.Doctrine, 25), GodEffect.Guard(StatId.FollowerFaith, 25), GodEffect.Resist(Pressure.Earth, 3), GodEffect.Chance("Revelation", 10) }, 1, 0, null),
        new("ya10", EyeSector.Yahweh, 10, AeonKind.Ascension, "찬탈: 질투하는 왕좌\u001FUsurpation: The Jealous Throne", "돌판을 깨고 질투하는 왕좌에 스스로 오릅니다.\u001FYou shatter the tablets and climb the jealous throne yourself.", System.Array.Empty<GodEffect>(), 0, 0, null),
        new("sa0g", EyeSector.Satan, 0, AeonKind.Good, "시험의 저울\u001FScales of Trial", "모든 행실을 다는 저울 앞에서 신도들이 스스로 몸가짐을 바로 합니다.\u001FBefore scales that weigh every deed the believers set themselves straight.", new[] { GodEffect.Guard(StatId.Authority, 6), GodEffect.Of(GodEffect.Type.SeizeGuard, 4), GodEffect.Yearly(PersonalStatId.Charity, 1) }, 0, 5, null),
        new("sa0e", EyeSector.Satan, 0, AeonKind.Evil, "첫 속삭임\u001FThe First Whisper", "귓가의 작은 속삭임이 헌금함으로 가는 손을 이끕니다.\u001FA small whisper at the ear guides hands toward the offering box.", new[] { GodEffect.Gain(StatId.Offerings, 10), GodEffect.Chance("Feast", 4), GodEffect.Yearly(PersonalStatId.Greed, 1) }, 1, 0, null),
        new("sa1g", EyeSector.Satan, 1, AeonKind.Good, "고발장\u001FThe Indictment", "죄를 적은 고발장이 먼저 나와 외부의 고발을 막아 섭니다.\u001FAn indictment listing your own sins comes first and blocks outside accusers.", new[] { GodEffect.Guard(StatId.Authority, 8), GodEffect.Of(GodEffect.Type.SeizeGuard, 5), GodEffect.Yearly(PersonalStatId.Charity, 1) }, 0, 5, null),
        new("sa1e", EyeSector.Satan, 1, AeonKind.Evil, "광야의 거래\u001FBargain in the Wilderness", "굶주린 광야에서 돌을 빵으로 바꾸자는 거래가 받아들여집니다.\u001FIn the hungry wilderness a bargain to turn stones into bread is accepted.", new[] { GodEffect.Gain(StatId.Offerings, 12), GodEffect.Chance("Feast", 5), GodEffect.Yearly(PersonalStatId.Greed, 1) }, 1, 0, null),
        new("sa2g", EyeSector.Satan, 2, AeonKind.Good, "욥의 인내\u001FPatience of Job", "모든 것을 잃고도 원망하지 않는 신도들이 교단을 버팁니다.\u001FBelievers who lose everything without complaint hold the cult together.", new[] { GodEffect.Guard(StatId.Authority, 10), GodEffect.Of(GodEffect.Type.SeizeGuard, 6), GodEffect.Yearly(PersonalStatId.Charity, 1) }, 0, 5, null),
        new("sa2e", EyeSector.Satan, 2, AeonKind.Evil, "보여 준 왕국들\u001FThe Kingdoms Shown", "높은 산에서 보여 준 세상의 왕국들이 신도들의 탐욕을 깨웁니다.\u001FThe kingdoms shown from the high mountain wake the believers' greed.", new[] { GodEffect.Gain(StatId.Offerings, 15), GodEffect.Chance("Feast", 6), GodEffect.Yearly(PersonalStatId.Greed, 1) }, 2, 0, null),
        new("sa3g", EyeSector.Satan, 3, AeonKind.Good, "참소의 법정\u001FCourt of Accusation", "참소하는 자의 법정에서 교단은 죄 없음을 증명해 냅니다.\u001FIn the Accuser's court the cult proves its innocence.", new[] { GodEffect.Guard(StatId.Authority, 12), GodEffect.Of(GodEffect.Type.SeizeGuard, 7), GodEffect.Yearly(PersonalStatId.Charity, 1) }, 0, 5, null),
        new("sa3e", EyeSector.Satan, 3, AeonKind.Evil, "금빛 계약\u001FThe Golden Contract", "금으로 적은 계약서에 서명한 자들이 재물을 끌어옵니다.\u001FThose who sign a contract written in gold draw riches in.", new[] { GodEffect.Gain(StatId.Offerings, 17), GodEffect.Chance("Feast", 7), GodEffect.Yearly(PersonalStatId.Greed, 1) }, 3, 0, null),
        new("sa4g", EyeSector.Satan, 4, AeonKind.Good, "의인의 시험\u001FTrial of the Righteous", "의인을 끝까지 시험하는 손길이 오히려 믿음을 단련합니다.\u001FThe hand that tests the righteous to the end only tempers their faith.", new[] { GodEffect.Guard(StatId.Authority, 14), GodEffect.Of(GodEffect.Type.SeizeGuard, 8), GodEffect.Yearly(PersonalStatId.Charity, 1) }, 0, 5, null),
        new("sa4e", EyeSector.Satan, 4, AeonKind.Evil, "떨어진 샛별\u001FThe Fallen Morning Star", "하늘에서 떨어진 샛별의 빛이 교단의 잔치를 밝힙니다.\u001FThe light of the fallen morning star illuminates the cult's feasts.", new[] { GodEffect.Gain(StatId.Offerings, 20), GodEffect.Chance("Feast", 8), GodEffect.Yearly(PersonalStatId.Greed, 1) }, 4, 0, null),
        new("sa5", EyeSector.Satan, 5, AeonKind.Gnosis, "사탄의 그노시스\u001FGnosis of Satan", "고발자가 하늘의 법정에서 일하는 하수인이었음을 깨닫습니다.\u001FYou realize the Accuser was only a servant working in heaven's court.", new[] { GodEffect.Gain(StatId.Offerings, 6), GodEffect.Gain(StatId.Doctrine, 3), GodEffect.Guard(StatId.Authority, 5), GodEffect.Resist(Pressure.Earth, 1), GodEffect.Chance("Feast", 2) }, 1, 0, null),
        new("sa6", EyeSector.Satan, 6, AeonKind.Gnosis, "헤브도마스 돌파\u001FBreaching the Hebdomad", "죄를 세던 일곱 하늘의 장부가 당신 앞에서 찢어집니다.\u001FThe ledgers of sin kept by the seven heavens tear apart before you.", new[] { GodEffect.Gain(StatId.Offerings, 12), GodEffect.Gain(StatId.Doctrine, 6), GodEffect.Guard(StatId.Authority, 10), GodEffect.Resist(Pressure.Earth, 1), GodEffect.Chance("Feast", 4) }, 1, 0, null),
        new("sa7", EyeSector.Satan, 7, AeonKind.Gnosis, "오그도아스\u001FThe Ogdoad", "고발도 변호도 없는 여덟째 하늘에 닿습니다.\u001FYou reach the eighth heaven where there is neither accusation nor defense.", new[] { GodEffect.Gain(StatId.Offerings, 18), GodEffect.Gain(StatId.Doctrine, 9), GodEffect.Guard(StatId.Authority, 15), GodEffect.Resist(Pressure.Earth, 2), GodEffect.Chance("Feast", 6) }, 1, 0, null),
