        new("sa9", EyeSector.Satan, 9, AeonKind.Gnosis, "플레로마의 문턱\u001FThreshold of the Pleroma", "어떤 저울도 닿지 않는 충만의 문 앞에 섭니다.\u001FYou stand at the gate of Fullness that no scale can reach.", new[] { GodEffect.Gain(StatId.Offerings, 30), GodEffect.Gain(StatId.Doctrine, 15), GodEffect.Guard(StatId.Authority, 25), GodEffect.Resist(Pressure.Earth, 3), GodEffect.Chance("Feast", 10) }, 1, 0, null),
        new("sa10", EyeSector.Satan, 10, AeonKind.Ascension, "찬탈: 고발자의 자리\u001FUsurpation: The Accuser's Seat", "고발자를 밀어내고 심판하는 자리에 앉습니다.\u001FYou push the Accuser aside and take the seat of judgment.", System.Array.Empty<GodEffect>(), 0, 0, null),
        new("sm0g", EyeSector.Samael, 0, AeonKind.Good, "눈먼 자의 고요\u001FStillness of the Blind", "보지 못하는 신의 고요가 신도들의 불안을 가라앉힙니다.\u001FThe stillness of the god who cannot see calms the believers' unrest.", new[] { GodEffect.Guard(PersonalStatId.Health, 6), GodEffect.Of(GodEffect.Type.VesselRecovery, 4), GodEffect.Yearly(PersonalStatId.Temperance, 1) }, 0, 5, null),
        new("sm0e", EyeSector.Samael, 0, AeonKind.Evil, "독의 이슬\u001FDew of Venom", "새벽 이슬에 섞인 독이 사람들을 들뜨게 하고 몸을 달굽니다.\u001FVenom mixed into the dawn dew stirs people and heats their bodies.", new[] { GodEffect.Gain(StatId.Followers, 10), GodEffect.Chance("Wonder", 4), GodEffect.Yearly(PersonalStatId.Lust, 1) }, 1, 0, null),
        new("sm1g", EyeSector.Samael, 1, AeonKind.Good, "어둠 속의 치유\u001FHealing in the Dark", "빛이 없는 방에서 병든 그릇이 조용히 회복됩니다.\u001FIn a lightless room the ailing vessel quietly recovers.", new[] { GodEffect.Guard(PersonalStatId.Health, 8), GodEffect.Of(GodEffect.Type.VesselRecovery, 5), GodEffect.Yearly(PersonalStatId.Temperance, 1) }, 0, 5, null),
        new("sm1e", EyeSector.Samael, 1, AeonKind.Evil, "죽음의 천사\u001FAngel of Death", "죽음의 천사가 지나간 자리에서 기적을 본 자들이 모여듭니다.\u001FThose who saw miracles where the Angel of Death passed come flocking.", new[] { GodEffect.Gain(StatId.Followers, 12), GodEffect.Chance("Wonder", 5), GodEffect.Yearly(PersonalStatId.Lust, 1) }, 1, 0, null),
        new("sm2g", EyeSector.Samael, 2, AeonKind.Good, "감은 눈의 기도\u001FPrayer of Closed Eyes", "눈을 감고 드리는 기도가 그릇을 흔들리지 않게 붙잡습니다.\u001FPrayer with closed eyes holds the vessel steady.", new[] { GodEffect.Guard(PersonalStatId.Health, 10), GodEffect.Of(GodEffect.Type.VesselRecovery, 6), GodEffect.Yearly(PersonalStatId.Temperance, 1) }, 0, 5, null),
        new("sm2e", EyeSector.Samael, 2, AeonKind.Evil, "뱀의 유혹\u001FThe Serpent's Temptation", "동산의 뱀처럼 달콤한 말이 금지된 열매로 손을 이끕니다.\u001FSweet words like the garden serpent's lead hands toward forbidden fruit.", new[] { GodEffect.Gain(StatId.Followers, 15), GodEffect.Chance("Wonder", 6), GodEffect.Yearly(PersonalStatId.Lust, 1) }, 2, 0, null),
        new("sm3g", EyeSector.Samael, 3, AeonKind.Good, "맹목의 자비\u001FBlind Mercy", "누구도 가리지 않는 맹목의 자비가 신도들의 몸을 돌봅니다.\u001FBlind mercy that excludes no one tends to the believers' bodies.", new[] { GodEffect.Guard(PersonalStatId.Health, 12), GodEffect.Of(GodEffect.Type.VesselRecovery, 7), GodEffect.Yearly(PersonalStatId.Temperance, 1) }, 0, 5, null),
        new("sm3e", EyeSector.Samael, 3, AeonKind.Evil, "독이 든 잔\u001FThe Poisoned Cup", "돌려 마신 잔 속의 독이 밤의 의식을 더 깊게 만듭니다.\u001FPoison in the shared cup makes the night rites run deeper.", new[] { GodEffect.Gain(StatId.Followers, 17), GodEffect.Chance("Wonder", 7), GodEffect.Yearly(PersonalStatId.Lust, 1) }, 3, 0, null),
        new("sm4g", EyeSector.Samael, 4, AeonKind.Good, "보지 않는 자의 평안\u001FPeace of the Unseeing", "보지 않기에 흔들리지 않는 평안이 교단을 감쌉니다.\u001FA peace that cannot be shaken because it does not look wraps the cult.", new[] { GodEffect.Guard(PersonalStatId.Health, 14), GodEffect.Of(GodEffect.Type.VesselRecovery, 8), GodEffect.Yearly(PersonalStatId.Temperance, 1) }, 0, 5, null),
        new("sm4e", EyeSector.Samael, 4, AeonKind.Evil, "눈먼 신의 오만\u001FPride of the Blind God", "자신이 유일하다 믿는 눈먼 신의 오만이 이적을 부풀립니다.\u001FThe blind god's pride in being the only one swells every miracle.", new[] { GodEffect.Gain(StatId.Followers, 20), GodEffect.Chance("Wonder", 8), GodEffect.Yearly(PersonalStatId.Lust, 1) }, 4, 0, null),
