        new("sm6", EyeSector.Samael, 6, AeonKind.Gnosis, "헤브도마스 돌파\u001FBreaching the Hebdomad", "눈먼 신이 지키던 일곱 하늘의 어둠을 뚫고 나갑니다.\u001FYou break through the darkness of the seven heavens the blind god guarded.", new[] { GodEffect.Gain(StatId.Followers, 12), GodEffect.Gain(StatId.Doctrine, 6), GodEffect.Guard(PersonalStatId.Health, 10), GodEffect.Resist(Pressure.Earth, 1), GodEffect.Chance("Wonder", 4) }, 1, 0, null),
        new("sm7", EyeSector.Samael, 7, AeonKind.Gnosis, "오그도아스\u001FThe Ogdoad", "처음으로 눈을 뜬 채 여덟째 하늘의 빛을 마주합니다.\u001FFor the first time you face the light of the eighth heaven with open eyes.", new[] { GodEffect.Gain(StatId.Followers, 18), GodEffect.Gain(StatId.Doctrine, 9), GodEffect.Guard(PersonalStatId.Health, 15), GodEffect.Resist(Pressure.Earth, 2), GodEffect.Chance("Wonder", 6) }, 1, 0, null),
