        new("sm9", EyeSector.Samael, 9, AeonKind.Gnosis, "플레로마의 문턱\u001FThreshold of the Pleroma", "보는 자만 들어갈 수 있는 충만의 문 앞에 섭니다.\u001FYou stand at the gate of Fullness that only those who see may enter.", new[] { GodEffect.Gain(StatId.Followers, 30), GodEffect.Gain(StatId.Doctrine, 15), GodEffect.Guard(PersonalStatId.Health, 25), GodEffect.Resist(Pressure.Earth, 3), GodEffect.Chance("Wonder", 10) }, 1, 0, null),
        new("sm10", EyeSector.Samael, 10, AeonKind.Ascension, "찬탈: 눈먼 왕좌\u001FUsurpation: The Blind Throne", "눈먼 왕좌에 앉아 이제는 당신이 무엇을 볼지 정합니다.\u001FYou take the blind throne and now decide what will be seen.", System.Array.Empty<GodEffect>(), 0, 0, null),
        new("yd0g", EyeSector.Yaldabaoth, 0, AeonKind.Good, "흙의 형상\u001FShape of Clay", "진흙으로 빚은 첫 형상이 교단의 몸이 되어 버팁니다.\u001FThe first figure shaped from clay becomes the cult's body and endures.", new[] { GodEffect.Guard(StatId.Reputation, 6), GodEffect.Resist(Pressure.Earth, 4), GodEffect.Yearly(PersonalStatId.Patience, 1) }, 0, 5, GodBuildingType.Shelter),
        new("yd0e", EyeSector.Yaldabaoth, 0, AeonKind.Evil, "사자의 포효\u001FThe Lion's Roar", "사자의 머리를 한 창조주의 포효가 사람들을 일하게 만듭니다.\u001FThe roar of the lion-headed creator drives people to labor.", new[] { GodEffect.Gain(StatId.Authority, 10), GodEffect.Chance("Consecrate", 4), GodEffect.Yearly(PersonalStatId.Appetite, 1) }, 1, 0, GodBuildingType.Statue),
        new("yd1g", EyeSector.Yaldabaoth, 1, AeonKind.Good, "아르콘의 질서\u001FOrder of the Archons", "아르콘들이 세운 질서가 바깥의 혼란을 막아 줍니다.\u001FThe order the Archons built holds back the chaos outside.", new[] { GodEffect.Guard(StatId.Reputation, 8), GodEffect.Resist(Pressure.Earth, 5), GodEffect.Yearly(PersonalStatId.Patience, 1) }, 0, 5, GodBuildingType.Library),
        new("yd1e", EyeSector.Yaldabaoth, 1, AeonKind.Evil, "일곱 아르콘\u001FThe Seven Archons", "일곱 아르콘이 각자의 하늘에서 권위를 나누어 줍니다.\u001FThe seven Archons hand out authority from their own heavens.", new[] { GodEffect.Gain(StatId.Authority, 12), GodEffect.Chance("Consecrate", 5), GodEffect.Yearly(PersonalStatId.Appetite, 1) }, 1, 0, GodBuildingType.Village),
        new("yd2g", EyeSector.Yaldabaoth, 2, AeonKind.Good, "빚어진 성소\u001FThe Molded Sanctuary", "손으로 빚은 성소가 신도들이 모일 자리를 마련합니다.\u001FA sanctuary molded by hand makes a place for believers to gather.", new[] { GodEffect.Guard(StatId.Reputation, 10), GodEffect.Resist(Pressure.Earth, 6), GodEffect.Yearly(PersonalStatId.Patience, 1) }, 0, 5, GodBuildingType.Temple),
        new("yd2e", EyeSector.Yaldabaoth, 2, AeonKind.Evil, "물질의 사슬\u001FChains of Matter", "물질에 묶인 자들이 사슬을 당기며 교단의 힘을 늘립니다.\u001FThose bound to matter pull their chains and swell the cult's power.", new[] { GodEffect.Gain(StatId.Authority, 15), GodEffect.Chance("Consecrate", 6), GodEffect.Yearly(PersonalStatId.Appetite, 1) }, 2, 0, null),
        new("yd3g", EyeSector.Yaldabaoth, 3, AeonKind.Good, "창조의 인내\u001FPatience of Creation", "세계를 엿새에 걸쳐 짓던 인내가 교단의 명성을 지킵니다.\u001FThe patience that built the world over six days guards the cult's renown.", new[] { GodEffect.Guard(StatId.Reputation, 12), GodEffect.Resist(Pressure.Earth, 7), GodEffect.Yearly(PersonalStatId.Patience, 1) }, 0, 5, null),
        new("yd3e", EyeSector.Yaldabaoth, 3, AeonKind.Evil, "나 외에 다른 신은 없다\u001FNo God Beside Me", "나 외에 다른 신은 없다는 외침이 교단의 권위를 끌어올립니다.\u001FThe cry that there is no other god raises the cult's authority.", new[] { GodEffect.Gain(StatId.Authority, 17), GodEffect.Chance("Consecrate", 7), GodEffect.Yearly(PersonalStatId.Appetite, 1) }, 3, 0, null),
        new("yd4g", EyeSector.Yaldabaoth, 4, AeonKind.Good, "세계의 기둥\u001FPillars of the World", "땅을 받치는 기둥처럼 교단의 기반이 흔들리지 않습니다.\u001FLike the pillars holding up the earth the cult's foundation stands firm.", new[] { GodEffect.Guard(StatId.Reputation, 14), GodEffect.Resist(Pressure.Earth, 8), GodEffect.Yearly(PersonalStatId.Patience, 1) }, 0, 5, null),
        new("yd4e", EyeSector.Yaldabaoth, 4, AeonKind.Evil, "뱀의 몸, 사자의 얼굴\u001FSerpent Body, Lion Face", "뱀의 몸에 사자의 얼굴을 한 창조주가 새 건물을 일으킵니다.\u001FThe serpent-bodied lion-faced creator raises new buildings.", new[] { GodEffect.Gain(StatId.Authority, 20), GodEffect.Chance("Consecrate", 8), GodEffect.Yearly(PersonalStatId.Appetite, 1) }, 4, 0, null),
        new("yd5", EyeSector.Yaldabaoth, 5, AeonKind.Gnosis, "얄다바오트의 그노시스\u001FGnosis of Yaldabaoth", "세계를 지은 자가 자신 위의 빛을 몰랐다는 것을 깨닫습니다.\u001FYou realize the maker of the world never knew the light above it.", new[] { GodEffect.Gain(StatId.Authority, 6), GodEffect.Gain(StatId.Doctrine, 3), GodEffect.Guard(StatId.Reputation, 5), GodEffect.Resist(Pressure.Earth, 1), GodEffect.Chance("Consecrate", 2) }, 1, 0, null),
        new("yd6", EyeSector.Yaldabaoth, 6, AeonKind.Gnosis, "헤브도마스 돌파\u001FBreaching the Hebdomad", "창조주가 지은 일곱 하늘의 벽을 넘어섭니다.\u001FYou climb past the walls of the seven heavens the creator built.", new[] { GodEffect.Gain(StatId.Authority, 12), GodEffect.Gain(StatId.Doctrine, 6), GodEffect.Guard(StatId.Reputation, 10), GodEffect.Resist(Pressure.Earth, 1), GodEffect.Chance("Consecrate", 4) }, 1, 0, null),
        new("yd7", EyeSector.Yaldabaoth, 7, AeonKind.Gnosis, "오그도아스\u001FThe Ogdoad", "지어지지 않은 여덟째 하늘에서 창조 너머를 봅니다.\u001FIn the unmade eighth heaven you look beyond creation.", new[] { GodEffect.Gain(StatId.Authority, 18), GodEffect.Gain(StatId.Doctrine, 9), GodEffect.Guard(StatId.Reputation, 15), GodEffect.Resist(Pressure.Earth, 2), GodEffect.Chance("Consecrate", 6) }, 1, 0, null),
        new("yd8", EyeSector.Yaldabaoth, 8, AeonKind.Gnosis, "소피아의 그림자\u001FShadow of Sophia", "창조주를 몰래 낳은 지혜의 그림자를 따라갑니다.\u001FYou follow the shadow of the Wisdom that secretly bore the creator.", new[] { GodEffect.Gain(StatId.Authority, 24), GodEffect.Gain(StatId.Doctrine, 12), GodEffect.Guard(StatId.Reputation, 20), GodEffect.Resist(Pressure.Earth, 2), GodEffect.Chance("Consecrate", 8) }, 1, 0, null),
        new("yd9", EyeSector.Yaldabaoth, 9, AeonKind.Gnosis, "플레로마의 문턱\u001FThreshold of the Pleroma", "물질이 끝나는 곳\u001F충만의 문 앞에 섭니다.", new[] { GodEffect.Gain(StatId.Authority, 30), GodEffect.Gain(StatId.Doctrine, 15), GodEffect.Guard(StatId.Reputation, 25), GodEffect.Resist(Pressure.Earth, 3), GodEffect.Chance("Consecrate", 10) }, 1, 0, null),
        new("yd10", EyeSector.Yaldabaoth, 10, AeonKind.Ascension, "찬탈: 물질의 왕좌\u001FUsurpation: The Throne of Matter", "물질의 왕좌를 빼앗아 세계를 당신의 손으로 다시 빚습니다.\u001FYou seize the throne of matter and remold the world with your own hands.", System.Array.Empty<GodEffect>(), 0, 0, null),
    };
}
